        while frame:
            co = frame.f_code
            if 'legacy' in co.co_name.lower():
                is_legacy = True
            frame = frame.f_back
    except Exception:
        pass

    if is_legacy:
        cost = 3.00 + (1.50 * weight_kg)
    else:
        cost = 4.00 + (1.75 * weight_kg)

    if express:
        cost *= 2.0
